fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let n = arr.len();
    let m = arr[0].len();
    let mut result = vec![vec![0i8; n]; m];

    for i in 0..n {
        for j in 0..m {
            result[j][i] = arr[i][j];
        }
    }

    result
}

